-- LIB-23 · Chords over the lyrics per key
--
-- Typed chords move from one set per song (songs.chord_lyrics + chords_key, LIB-22) to one set
-- per key (song_keys.chord_lyrics). The backfill puts each song's chords on the key they were
-- written in, or on the song's primary key when that key isn't one of its keys (or wasn't
-- stated).
--
-- Deploy safety: only adds a nullable column and copies data. The build still live while this
-- runs keeps reading and writing songs.chord_lyrics; those columns stay until a later
-- migration drops them. Column and check generated by drizzle-kit from db/schema/keys.ts; the
-- backfill is by hand.

ALTER TABLE "song_keys" ADD COLUMN "chord_lyrics" jsonb;--> statement-breakpoint
ALTER TABLE "song_keys" ADD CONSTRAINT "song_keys_chord_lyrics_check" CHECK (jsonb_typeof("song_keys"."chord_lyrics") = 'object');--> statement-breakpoint
UPDATE "song_keys" sk
SET "chord_lyrics" = s."chord_lyrics"
FROM "songs" s
WHERE sk."song_id" = s."id"
  AND s."chord_lyrics" IS NOT NULL
  AND sk."chord_lyrics" IS NULL
  AND sk."key" = COALESCE(
    (SELECT k."key" FROM "song_keys" k WHERE k."song_id" = s."id" AND k."key" = s."chords_key"),
    (SELECT k."key" FROM "song_keys" k WHERE k."song_id" = s."id" AND k."is_primary")
  );
